import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product } from '../types';

export const StorePage: React.FC = () => {
    const { vendorId } = useParams<{ vendorId: string }>();
    const navigate = useNavigate();
    const { vendors, products, addToCart, cart, removeFromCart, toggleFavorite, favorites, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const vendorProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');

    if (!vendor) return <div className="p-8 text-center text-gray-500 dark:text-gray-400">Store not found</div>;

    const whatsappUrl = vendor.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your store on LYNQED!`
        : null;

    const handleShare = async () => {
        const shareData = {
            title: `Check out ${vendor.storeName} on LYNQED!`,
            text: `Find amazing products at ${vendor.storeName} on campus.`,
            url: window.location.href
        };

        try {
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                await navigator.clipboard.writeText(window.location.href);
                showToast("Store link copied to clipboard!", "success");
            }
        } catch (err) {
            console.error("Error sharing:", err);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Store Header */}
            <div className="bg-white dark:bg-darkSurface p-6 shadow-sm border-b border-gray-100 dark:border-gray-800">
                <div className="flex items-center gap-4">
                     <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="xl" />
                     <div className="flex-1">
                         <div className="flex items-center gap-2">
                            <h1 className="text-xl font-display font-bold text-gray-900 dark:text-white">{vendor.storeName}</h1>
                            {vendor.isApproved && <i className="fa-solid fa-circle-check text-blue-500 text-sm"></i>}
                         </div>
                         <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mt-1 mb-2">
                             <i className="fa-solid fa-location-dot text-red-500"></i> {vendor.location}
                             <span className="mx-1">•</span>
                             <i className="fa-solid fa-star text-yellow-400"></i> {vendor.rating}
                         </div>
                         <p className="text-sm text-gray-600 dark:text-gray-400 line-clamp-2">{vendor.storeDescription}</p>
                     </div>
                </div>

                {/* Actions */}
                <div className="grid grid-cols-2 gap-3 mt-4">
                     {whatsappUrl && (
                        <a 
                            href={whatsappUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center justify-center gap-2 bg-[#25D366] text-white py-2.5 rounded-xl text-sm font-bold hover:bg-[#128C7E] transition-all shadow-md active:scale-95"
                        >
                            <i className="fa-brands fa-whatsapp text-lg"></i> Chat on WhatsApp
                        </a>
                     )}
                     <button 
                        onClick={handleShare}
                        className="flex items-center justify-center gap-2 bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 py-2.5 rounded-xl text-sm font-bold hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors border border-gray-100 dark:border-gray-700"
                    >
                        <i className="fa-solid fa-share-nodes"></i> Share Store
                     </button>
                </div>
            </div>

            {/* Product Grid */}
            <div className="p-4">
                <h2 className="font-bold text-gray-800 dark:text-gray-200 mb-4 text-sm uppercase tracking-wide">Products ({vendorProducts.length})</h2>
                {vendorProducts.length === 0 ? (
                    <div className="text-center py-10 text-gray-400 dark:text-gray-500">No products available.</div>
                ) : (
                    <div className="grid grid-cols-2 gap-3">
                        {vendorProducts.map(product => {
                            const isFav = favorites.includes(product.id);
                            const isInCart = cart.some(item => item.productId === product.id);

                            return (
                                <div 
                                    key={product.id} 
                                    className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 hover:shadow-xl transition-all duration-300 group relative flex flex-col h-full cursor-pointer"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-[4/5] w-full relative overflow-hidden bg-white dark:bg-gray-900">
                                        <img 
                                            src={product.images[0]} 
                                            alt={product.title} 
                                            className="w-full h-full object-cover p-0 transition-transform duration-700 group-hover:scale-110" 
                                        />
                                        <button 
                                            className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 dark:bg-darkBg/80 backdrop-blur-sm border border-gray-100 dark:border-gray-800 hover:border-red-100 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors shadow-sm active:scale-90"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleFavorite(product.id);
                                            }}
                                        >
                                            <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-xs`}></i>
                                        </button>
                                        {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-10"><span className="bg-black/80 text-white text-[10px] px-3 py-1 rounded font-bold uppercase tracking-wide">Out of Stock</span></div>}
                                    </div>
                                    <div className="p-3 bg-white dark:bg-darkSurface flex flex-col justify-between flex-grow relative z-10">
                                        <div>
                                            <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3>
                                        </div>
                                        <div className="flex items-center justify-between mt-2">
                                            <span className="text-sm font-extrabold text-gray-900 dark:text-white">{product.currency}{product.price.toFixed(2)}</span>
                                            <button 
                                                className={`w-8 h-8 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 group-btn ${product.stock === 0 ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : isInCart ? 'bg-green-500 hover:bg-red-500' : 'bg-black dark:bg-white dark:text-black hover:bg-primary'}`}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (product.stock > 0) {
                                                        isInCart ? removeFromCart(product.id) : addToCart(product);
                                                    }
                                                }}
                                                disabled={product.stock === 0}
                                            >
                                                <i className={`fa-solid ${isInCart ? 'fa-check group-btn-hover:fa-trash' : 'fa-plus'} text-xs ${isInCart ? 'group-hover:hidden' : ''}`}></i>
                                                {isInCart && <i className="fa-solid fa-trash text-xs hidden group-hover:inline"></i>}
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, removeFromCart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast } = useApp();
    const [selectedImageIndex, setSelectedImageIndex] = useState(0);

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    // Recommendations
    const relatedProducts = products
        .filter(p => p.category === product?.category && p.id !== product?.id)
        .slice(0, 8); // Increased count for better swiping feel

    const [quantity, setQuantity] = useState(1);

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const cartItem = cart.find(i => i.productId === product.id);
    const isInCart = !!cartItem;
    const isFav = favorites.includes(product.id);

    // Sync local quantity with cart if present
    useEffect(() => {
        if (cartItem) setQuantity(cartItem.quantity);
    }, [cartItem]);

    const handleQuantity = (delta: number) => {
        const newQ = Math.max(1, Math.min(product.stock, quantity + delta));
        setQuantity(newQ);
        if (isInCart) updateCartQuantity(product.id, newQ);
    };

    const handleBuyNow = () => {
        if (isInCart) {
            updateCartQuantity(product.id, quantity);
        } else {
            addToCart(product, quantity);
        }
        navigate('/buyer/checkout');
    };

    const handleShare = async () => {
        const shareData = {
            title: product.title,
            text: `Check out this ${product.title} from ${vendor?.storeName || 'LYNQED'}!`,
            url: window.location.href
        };

        try {
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                await navigator.clipboard.writeText(window.location.href);
                showToast("Product link copied to clipboard!", "success");
            }
        } catch (err) {
            console.error("Error sharing:", err);
        }
    };

    const whatsappUrl = vendor?.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your product "${product.title}" on LYNQED and I'm interested!`
        : null;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Breadcrumbs & Header */}
            <div className="bg-white dark:bg-darkSurface border-b border-gray-200 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center gap-3 shadow-sm">
                <button onClick={() => navigate(-1)} className="text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="text-xs text-gray-500 dark:text-gray-400 breadcrumbs flex items-center gap-2 overflow-hidden whitespace-nowrap">
                    <Link to="/buyer/dashboard" className="hover:text-primary dark:hover:text-primaryLight">Home</Link>
                    <i className="fa-solid fa-chevron-right text-[8px]"></i>
                    <span>{product.category}</span>
                    <i className="fa-solid fa-chevron-right text-[8px]"></i>
                    <span className="text-gray-900 dark:text-white font-bold truncate">{product.title}</span>
                </div>
                <div className="ml-auto flex gap-3">
                    <button onClick={() => toggleFavorite(product.id)} className={`${isFav ? 'text-red-500' : 'text-gray-400 dark:text-gray-500'} hover:text-red-600 transition-colors`}>
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart text-lg`}></i>
                    </button>
                    <button onClick={handleShare} className="text-gray-400 dark:text-gray-500 hover:text-blue-500">
                        <i className="fa-solid fa-share-nodes text-lg"></i>
                    </button>
                </div>
            </div>

            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="bg-white dark:bg-darkSurface rounded-2xl shadow-card overflow-hidden grid grid-cols-1 md:grid-cols-2 gap-0 md:gap-8">

                    {/* Left: Image Gallery */}
                    <div className="p-4 md:p-8 bg-white dark:bg-darkSurface flex flex-col gap-4">
                        <div className="aspect-square w-full bg-gray-50 dark:bg-gray-900 rounded-2xl overflow-hidden border border-gray-100 dark:border-gray-800 relative group">
                            <img 
                                src={product.images[selectedImageIndex]} 
                                alt={product.title} 
                                className="w-full h-full object-contain mix-blend-multiply dark:mix-blend-normal transition-transform duration-500 group-hover:scale-105" 
                            />
                            {product.stock === 0 && (
                                <div className="absolute top-4 left-4 bg-red-600 text-white text-xs font-bold px-3 py-1 rounded shadow-sm">
                                    SOLD OUT
                                </div>
                            )}
                        </div>
                        {/* Thumbnails */}
                        {product.images.length > 1 && (
                            <div className="flex gap-2 overflow-x-auto hide-scrollbar">
                                {product.images.map((img, idx) => (
                                    <div 
                                        key={idx} 
                                        onClick={() => setSelectedImageIndex(idx)}
                                        className={`w-16 h-16 rounded-lg border-2 cursor-pointer overflow-hidden flex-shrink-0 ${selectedImageIndex === idx ? 'border-primary' : 'border-gray-100 dark:border-gray-800 hover:border-gray-300 dark:hover:border-gray-600'}`}
                                    >
                                        <img src={img} className="w-full h-full object-cover" />
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Right: Product Info */}
                    <div className="p-4 md:p-8 md:border-l border-gray-100 dark:border-gray-800 flex flex-col">
                        <div className="mb-4">
                            <span className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider">{product.category}</span>
                            <h1 className="text-2xl md:text-3xl font-display font-bold text-gray-900 dark:text-white mt-1 leading-tight">{product.title}</h1>
                            <div className="flex items-center gap-2 mt-2">
                                <div className="flex text-yellow-400 text-xs">
                                    {[1,2,3,4,5].map(i => <i key={i} className={`fa-solid fa-star ${i <= (product.rating||0) ? '' : 'text-gray-200 dark:text-gray-700'}`}></i>)}
                                </div>
                                <span className="text-xs text-gray-500 dark:text-gray-400">(24 verified ratings)</span>
                            </div>
                        </div>

                        {/* Price Strip - Franko Style */}
                        <div className="bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/20 rounded-xl p-4 mb-6 flex justify-between items-center">
                            <div>
                                <p className="text-xs text-red-400 font-bold uppercase mb-1">Special Price</p>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-3xl font-black text-red-600 dark:text-red-500">{product.currency}{product.price.toFixed(2)}</span>
                                    <span className="text-sm text-gray-400 dark:text-gray-600 line-through decoration-red-300 dark:decoration-red-900">{(product.price * 1.2).toFixed(2)}</span>
                                </div>
                            </div>
                            <div className="text-right">
                                <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold border ${product.stock > 0 ? 'bg-green-100 dark:bg-green-900/20 text-green-700 dark:text-green-500 border-green-200 dark:border-green-800' : 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400 border-gray-200 dark:border-gray-700'}`}>
                                    {product.stock > 0 ? 'In Stock' : 'Sold Out'}
                                </span>
                            </div>
                        </div>

                        {/* Description */}
                        <div className="mb-6">
                            <h3 className="font-bold text-gray-900 dark:text-white text-sm mb-2">Product Details</h3>
                            <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed whitespace-pre-line">
                                {product.description}
                            </p>
                        </div>

                        {/* Actions */}
                        <div className="mt-auto border-t border-gray-100 dark:border-gray-800 pt-6">
                            <div className="flex gap-3 mb-4">
                                {/* Quantity */}
                                <div className="flex items-center border border-gray-300 dark:border-gray-700 rounded-lg h-12 w-28 bg-white dark:bg-darkBg">
                                    <button 
                                        onClick={() => handleQuantity(-1)}
                                        disabled={quantity <= 1}
                                        className="w-8 h-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-50"
                                    >
                                        <i className="fa-solid fa-minus text-xs"></i>
                                    </button>
                                    <span className="flex-1 text-center font-bold text-gray-900 dark:text-white">{quantity}</span>
                                    <button 
                                        onClick={() => handleQuantity(1)}
                                        disabled={quantity >= product.stock}
                                        className="w-8 h-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-50"
                                    >
                                        <i className="fa-solid fa-plus text-xs"></i>
                                    </button>
                                </div>

                                {/* WhatsApp Chat (New Restored Position) */}
                                {whatsappUrl && (
                                    <a 
                                        href={whatsappUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="w-12 h-12 bg-[#25D366] text-white rounded-lg flex items-center justify-center shadow-lg hover:scale-105 active:scale-95 transition-all"
                                        title="Chat with vendor"
                                    >
                                        <i className="fa-brands fa-whatsapp text-2xl"></i>
                                    </a>
                                )}

                                {/* Buy Now Button */}
                                <button 
                                    onClick={handleBuyNow}
                                    disabled={product.stock === 0}
                                    className={`flex-1 h-12 rounded-lg font-bold text-white shadow-lg flex items-center justify-center gap-2 transition-all active:scale-[0.98] bg-gradient-to-r from-orange-500 to-red-600 hover:from-orange-600 hover:to-red-700 ${product.stock === 0 ? 'opacity-50 cursor-not-allowed grayscale' : ''}`}
                                >
                                    <i className="fa-solid fa-bolt"></i> Buy Now
                                </button>
                            </div>

                            {/* Vendor Info / Trust */}
                            <div className="bg-gray-50 dark:bg-darkBg rounded-xl p-3 flex items-center gap-3 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors border border-gray-100 dark:border-gray-800" onClick={() => navigate(`/store/${vendor?.vendorId}`)}>
                                <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || 'Vendor'} size="md" />
                                <div className="flex-1">
                                    <p className="text-xs text-gray-400 dark:text-gray-500 uppercase font-bold">Sold by</p>
                                    <p className="text-sm font-bold text-gray-900 dark:text-white">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center gap-2">
                                     <span className="text-[10px] font-bold text-primary uppercase">Visit Store</span>
                                     <i className="fa-solid fa-chevron-right text-xs text-gray-300"></i>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Products - Horizontal Swippable Scroller */}
                {relatedProducts.length > 0 && (
                    <div className="mt-12 overflow-hidden">
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="font-display font-bold text-xl text-gray-900 dark:text-white">You May Also Like</h3>
                            <div className="flex gap-2">
                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest hidden md:block">Swipe to explore</span>
                            </div>
                        </div>
                        <div className="flex gap-4 overflow-x-auto hide-scrollbar snap-x snap-mandatory pb-4 -mx-1 px-1">
                            {relatedProducts.map(rp => (
                                <div 
                                    key={rp.id}
                                    onClick={() => {
                                        navigate(`/buyer/product/${rp.id}`);
                                        window.scrollTo(0,0);
                                    }}
                                    className="min-w-[180px] md:min-w-[220px] bg-white dark:bg-darkSurface rounded-2xl border border-gray-100 dark:border-gray-800 p-3 shadow-sm hover:shadow-md transition-all cursor-pointer group snap-start"
                                >
                                    <div className="aspect-square bg-gray-50 dark:bg-gray-900 rounded-xl overflow-hidden mb-3 relative">
                                        <img src={rp.images[0]} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                                        <div className="absolute bottom-2 right-2 bg-white/90 dark:bg-darkBg/90 backdrop-blur-sm px-2 py-1 rounded-lg text-[10px] font-black text-gray-900 dark:text-white shadow-sm">
                                            {rp.currency}{rp.price}
                                        </div>
                                    </div>
                                    <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-1">{rp.title}</h4>
                                    <div className="flex items-center justify-between mt-2">
                                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter truncate max-w-[100px]">{rp.category}</span>
                                        <button className="w-6 h-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[10px] hover:bg-primary hover:text-white transition-colors">
                                            <i className="fa-solid fa-plus"></i>
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export const Cart: React.FC = () => {
    const { cart, removeFromCart, updateCartQuantity, clearCart } = useApp();
    const navigate = useNavigate();

    const subtotal = cart.reduce((s, i) => s + i.product.price * i.quantity, 0);

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-safe">
             <div className="bg-white dark:bg-darkSurface p-4 shadow-sm sticky top-0 z-10 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <button onClick={() => navigate(-1)} className="dark:text-white"><i className="fa-solid fa-arrow-left"></i></button>
                    <h1 className="text-xl font-bold font-display dark:text-white">My Cart ({cart.length})</h1>
                </div>
                {cart.length > 0 && <button onClick={clearCart} className="text-xs text-red-500 font-bold">Clear All</button>}
             </div>

             <div className="p-4 space-y-4">
                {cart.length === 0 ? (
                    <div className="text-center py-20 text-gray-400 dark:text-gray-500">
                        <i className="fa-solid fa-cart-arrow-down text-4xl mb-4 opacity-20"></i>
                        <p>Your cart is empty.</p>
                        <Button className="mt-4" onClick={() => navigate('/buyer/dashboard')}>Start Shopping</Button>
                    </div>
                ) : (
                    cart.map(item => (
                        <Card key={item.productId} className="p-3 flex gap-3 items-center">
                            <div className="w-20 h-20 bg-gray-100 dark:bg-gray-900 rounded-xl overflow-hidden flex-shrink-0">
                                <img src={item.product.images[0]} className="w-full h-full object-cover" />
                            </div>
                            <div className="flex-1">
                                <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-1">{item.product.title}</h4>
                                <p className="text-primary dark:text-primaryLight font-bold text-sm">₵{item.product.price.toFixed(2)}</p>

                                <div className="flex items-center justify-between mt-2">
                                    <div className="flex items-center bg-gray-50 dark:bg-darkBg rounded-lg h-8">
                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity - 1)} className="w-8 h-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"><i className="fa-solid fa-minus text-[10px]"></i></button>
                                        <span className="text-xs font-bold w-6 text-center dark:text-white">{item.quantity}</span>
                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity + 1)} className="w-8 h-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"><i className="fa-solid fa-plus text-[10px]"></i></button>
                                    </div>
                                    <button onClick={() => removeFromCart(item.productId)} className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 transition-colors">
                                        <i className="fa-solid fa-trash text-sm"></i>
                                    </button>
                                </div>
                            </div>
                        </Card>
                    ))
                )}

                {cart.length > 0 && (
                    <div className="mt-6 pt-4 border-t border-gray-200 dark:border-gray-800">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-gray-500 dark:text-gray-400 text-sm">Subtotal</span>
                            <span className="font-bold text-gray-900 dark:text-white">₵{subtotal.toFixed(2)}</span>
                        </div>
                        <p className="text-xs text-gray-400 dark:text-gray-600 mb-6 text-right">Delivery fees calculated at checkout</p>

                        <Button fullWidth size="lg" onClick={() => navigate('/buyer/checkout')} className="shadow-xl shadow-primary/20">
                            Proceed to Pay
                        </Button>
                    </div>
                )}
             </div>
        </div>
    );
};

export const Checkout: React.FC = () => {
    const { cart, placeOrder, currentUser, signup, login } = useApp();
    const navigate = useNavigate();
    const [method, setMethod] = useState<'delivery' | 'pickup'>('delivery');
    const [isPlacing, setIsPlacing] = useState(false);
    const [guestEmail, setGuestEmail] = useState('');
    const [deliveryFee, setDeliveryFee] = useState(10); 

    useEffect(() => {
        if (method === 'pickup') {
            setDeliveryFee(0);
        } else {
            setDeliveryFee(15.00); 
        }
    }, [method]);

    const handleOrder = async () => {
        if (!currentUser && !guestEmail) { alert("Email required for guest checkout"); return; }

        setIsPlacing(true);

        try {
            if (!currentUser) {
                const shadowPass = 'guest123'; 
                const regRes = await signup(guestEmail, shadowPass, 'Guest User', 'buyer');

                if (!regRes.success) {
                     const loginRes = await login(guestEmail, shadowPass);
                     if (!loginRes.success) {
                         alert("This email is already registered. Please Login first.");
                         setIsPlacing(false);
                         return;
                     }
                }
            }

            await placeOrder(method, deliveryFee);
            setTimeout(() => { 
                setIsPlacing(false); 
                navigate('/buyer/orders'); 
            }, 2000);

        } catch (e) {
            console.error(e);
            setIsPlacing(false);
            alert("Checkout failed. Please try again.");
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const total = subtotal + deliveryFee;

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in pb-safe">
            <h1 className="text-2xl font-display font-bold mb-6 dark:text-white">Checkout</h1>

            {!currentUser && (
                <Card className="p-4 mb-4">
                    <h3 className="font-bold text-sm mb-2 dark:text-white">Guest Checkout</h3>
                    <Input label="Email Address" value={guestEmail} onChange={e => setGuestEmail(e.target.value)} placeholder="Enter email for receipt" />
                    <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">We'll create a temporary account for you to track this order.</p>
                </Card>
            )}

            <div className="grid grid-cols-2 gap-4 mb-6">
                <div onClick={() => setMethod('delivery')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'delivery' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-motorcycle text-xl mb-2"></i>
                    <p className="font-bold text-sm">Delivery</p>
                    <p className="text-xs opacity-70">₵{deliveryFee}</p>
                </div>
                <div onClick={() => setMethod('pickup')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'pickup' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-person-walking text-xl mb-2"></i>
                    <p className="font-bold text-sm">Pickup</p>
                    <p className="text-xs opacity-70">Free</p>
                </div>
            </div>

            <Card className="p-5">
                <h3 className="font-bold mb-4 dark:text-white">Summary</h3>
                <div className="space-y-2">
                    {cart.map(i => <div key={i.productId} className="flex justify-between text-sm dark:text-gray-400"><span>{i.product.title} x{i.quantity}</span><span className="dark:text-white">₵{i.product.price * i.quantity}</span></div>)}
                </div>
                <div className="border-t border-dashed dark:border-gray-800 my-4"></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Subtotal</span><span className="dark:text-white">₵{subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Fee</span><span className="dark:text-white">₵{deliveryFee.toFixed(2)}</span></div>
                <div className="flex justify-between font-bold text-lg mt-2 dark:text-white"><span>Total</span><span>₵{total.toFixed(2)}</span></div>
            </Card>

            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-darkSurface border-t border-gray-100 dark:border-gray-800">
                <Button fullWidth size="lg" onClick={handleOrder} disabled={isPlacing}>
                    {isPlacing ? 'Processing Order...' : `Pay ₵${total.toFixed(2)}`}
                </Button>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';

// --- Avatar ---
interface AvatarProps {
  src?: string | null;
  name: string;
  size?: 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  className?: string;
  onClick?: () => void;
}

export const Avatar: React.FC<AvatarProps> = ({ src, name, size = 'md', className = '', onClick }) => {
  const [imgError, setImgError] = useState(false);

  useEffect(() => {
    setImgError(false);
  }, [src]);

  const initials = name
    ? name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase()
    : '?';

  const sizeClasses = {
    sm: "w-8 h-8 text-[10px]",
    md: "w-10 h-10 text-xs",
    lg: "w-14 h-14 text-sm",
    xl: "w-24 h-24 text-xl",
    '2xl': "w-32 h-32 text-3xl"
  };

  const colors = [
    'bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-400',
    'bg-green-100 text-green-600 dark:bg-green-900/40 dark:text-green-400',
    'bg-yellow-100 text-yellow-600 dark:bg-yellow-900/40 dark:text-yellow-400',
    'bg-purple-100 text-purple-600 dark:bg-purple-900/40 dark:text-purple-400',
    'bg-pink-100 text-pink-600 dark:bg-pink-900/40 dark:text-pink-400',
    'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/40 dark:text-indigo-400',
  ];
  const colorIndex = name.length % colors.length;
  const colorClass = colors[colorIndex];

  const baseClasses = `rounded-full flex items-center justify-center font-bold object-cover shadow-sm border border-white dark:border-gray-800 flex-shrink-0 ${sizeClasses[size]} ${className}`;

  if (src && !imgError) {
    return (
      <img 
        src={src} 
        alt={name} 
        className={`${baseClasses} bg-gray-100 dark:bg-gray-800`}
        onError={() => setImgError(true)}
        onClick={onClick}
      />
    );
  }

  return (
    <div className={`${baseClasses} ${colorClass}`} onClick={onClick} title={name}>
      {initials}
    </div>
  );
};

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'success';
  fullWidth?: boolean;
  size?: 'sm' | 'md' | 'lg';
  icon?: string;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', fullWidth, size = 'md', icon, className = '', ...props 
}) => {
  const base = "inline-flex items-center justify-center rounded-2xl font-semibold transition-all duration-300 active:scale-[0.96] disabled:opacity-50 disabled:active:scale-100 tracking-tight";

  const variants = {
    primary: "bg-gradient-to-r from-primary to-primaryDark text-white hover:shadow-glow shadow-lg shadow-primary/30 border border-transparent",
    secondary: "bg-white dark:bg-darkSurface text-gray-800 dark:text-white border border-gray-100 dark:border-gray-800 hover:bg-gray-50 dark:hover:bg-gray-800 shadow-sm",
    outline: "border-2 border-primary/20 text-primary dark:text-primaryLight bg-transparent hover:bg-primary/5",
    ghost: "bg-transparent text-gray-500 dark:text-gray-400 hover:bg-gray-100/50 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-white shadow-none",
    danger: "bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 border border-red-100 dark:border-red-900/30",
    success: "bg-green-500 text-white hover:bg-green-600 shadow-lg shadow-green-500/30 border border-transparent"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-5 py-3 text-sm",
    lg: "px-8 py-4 text-base"
  };

  return (
    <button 
      className={`${base} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {icon && <i className={`fa-solid fa-${icon} mr-2.5 ${size === 'sm' ? 'text-xs' : 'text-sm'}`}></i>}
      {children}
    </button>
  );
};

