export const BuyerDashboard: React.FC = () => {
  const { products, vendors, favorites, toggleFavorite, currentUser, addToCart, removeFromCart, cart, showToast, isDataLoading } = useApp();
  const navigate = useNavigate();
  const [selectedCat, setSelectedCat] = useState('All');
  const [sortType, setSortType] = useState<'nearby' | 'price' | 'rating'>('nearby');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
              (position) => {
                  setUserLocation({
                      lat: position.coords.latitude,
                      lng: position.coords.longitude
                  });
              },
              (error) => {
                  console.log("GPS Denied", error);
                  setUserLocation({ lat: 5.6506, lng: -0.1962 });
              }
          );
      }
  }, []);

  const getDistanceFromLatLonInKm = (lat1: number, lon1: number, lat2: number, lon2: number) => {
      const R = 6371; 
      const dLat = (lat2 - lat1) * (Math.PI/180);
      const dLon = (lon2 - lon1) * (Math.PI/180);
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(lat1 * (Math.PI/180)) * Math.cos(lat2 * (Math.PI/180)) * 
        Math.sin(dLon/2) * Math.sin(dLon/2); 
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)); 
      return R * c;
  };

  const getCoordsForLocation = (locStr: string): {lat: number, lng: number} | null => {
      const clean = locStr.toLowerCase();
      if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
      const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
      if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
      return null;
  };

  const categoryList = useMemo(() => {
      const standardNames = new Set(CATEGORIES.map(c => c.name));
      const customCategories = Array.from(new Set(products.map(p => p.category)))
        .filter(cat => cat && !standardNames.has(cat) && cat !== 'OTHER')
        .map(cat => {
            const sampleProduct = products.find(p => p.category === cat);
            return {
                id: `cat-custom-${cat.replace(/\s+/g, '-').toLowerCase()}`,
                name: cat,
                icon: 'tag',
                image: sampleProduct?.images[0] || 'https://via.placeholder.com/150?text=' + cat
            };
        });

      return [
          { id: 'cat-all', name: 'All', icon: 'layer-group', image: '' },
          ...CATEGORIES,
          ...customCategories
      ];
  }, [products]);

  const trendingProducts = useMemo(() => {
      return products.filter(p => p.status === 'approved' && p.stock > 0).slice(0, 6);
  }, [products]);

  const sortedProducts = useMemo(() => {
      const approvedProducts = products.filter(p => p.status === 'approved');
      let filtered = selectedCat === 'All' 
         ? approvedProducts 
         : approvedProducts.filter(p => p.category === selectedCat);

      if (sortType === 'price') return [...filtered].sort((a, b) => a.price - b.price);
      if (sortType === 'rating') return [...filtered].sort((a, b) => (b.rating || 0) - (a.rating || 0));
      if (sortType === 'nearby' && userLocation) {
          return [...filtered].sort((a, b) => {
              const coordsA = getCoordsForLocation(a.location);
              const coordsB = getCoordsForLocation(b.location);
              const distA = coordsA ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsA.lat, coordsA.lng) : 999;
              const distB = coordsB ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsB.lat, coordsB.lng) : 999;
              return distA - distB;
          });
      }
      return filtered;
  }, [products, selectedCat, sortType, userLocation]);

  const handleStartSelling = () => {
      if (!currentUser) navigate('/register', { state: { role: 'vendor' } });
      else if (currentUser.roles.includes('vendor')) navigate('/vendor/dashboard');
      else navigate('/vendor/onboarding');
  };

  return (
    <div className="flex flex-col space-y-5 animate-fade-in pb-4 bg-gray-50 dark:bg-darkBg min-h-screen">

      {/* Search Header */}
      <div className="bg-white/90 dark:bg-darkSurface/90 backdrop-blur-xl pt-2 pb-3 px-4 sticky top-0 z-30 border-b border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="relative group" onClick={() => navigate('/buyer/search')}>
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <i className="fa-solid fa-magnifying-glass text-gray-400 group-hover:text-primary transition-colors"></i>
            </div>
            <input 
                readOnly
                placeholder="Search campus stores..." 
                className="block w-full rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-darkBg py-2.5 pl-10 pr-4 text-sm text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none cursor-pointer hover:bg-white dark:hover:bg-darkSurface hover:border-primary/30 transition-all"
            />
        </div>
      </div>

      {/* Categories Scroller - Swippable with Snapping */}
      <div className="pl-4">
        <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest mb-3 pr-4">Shop By Category</h3>
        <div className="flex gap-3 overflow-x-auto hide-scrollbar snap-x snap-mandatory pb-2 pr-4">
            {categoryList.map(cat => {
                const isSelected = selectedCat === cat.name;
                return (
                    <div 
                        key={cat.id} 
                        className="flex flex-col items-center justify-center gap-1 cursor-pointer min-w-[72px] snap-start"
                        onClick={() => setSelectedCat(cat.name)}
                    >
                        <div className={`w-14 h-14 rounded-full flex items-center justify-center transition-all overflow-hidden shadow-sm border-2 ${isSelected ? 'border-primary ring-2 ring-primary/20' : 'border-transparent'}`}>
                            {cat.image ? (
                                <img src={cat.image} alt={cat.name} className="w-full h-full object-cover" />
                            ) : (
                                <div className={`w-full h-full flex items-center justify-center bg-gray-200 dark:bg-darkSurface text-gray-500 dark:text-gray-400`}>
                                    <i className={`fa-solid fa-${cat.icon} text-lg`}></i>
                                </div>
                            )}
                        </div>
                        <span className={`text-[10px] font-bold text-center w-full uppercase ${isSelected ? 'text-primary' : 'text-gray-500 dark:text-gray-400'}`}>
                            {cat.name}
                        </span>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Trending / Featured Swippable Section */}
      <div className="pl-4">
        <div className="flex justify-between items-center mb-3 pr-4">
            <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest">Trending Now</h3>
            <button onClick={() => navigate('/buyer/search')} className="text-[10px] font-black text-primary uppercase">View Map</button>
        </div>
        <div className="flex gap-4 overflow-x-auto hide-scrollbar snap-x snap-mandatory pr-4 pb-2">
            {trendingProducts.map(p => (
                <div 
                    key={p.id}
                    onClick={() => navigate(`/buyer/product/${p.id}`)}
                    className="min-w-[140px] bg-white dark:bg-darkSurface rounded-2xl p-2 shadow-sm border border-gray-100 dark:border-gray-800 snap-start active:scale-95 transition-transform"
                >
                    <div className="aspect-square rounded-xl overflow-hidden mb-2 bg-gray-50 dark:bg-gray-900">
                        <img src={p.images[0]} className="w-full h-full object-cover" />
                    </div>
                    <p className="text-[10px] font-bold text-gray-900 dark:text-white line-clamp-1">{p.title}</p>
                    <p className="text-xs font-black text-primary mt-1">₵{p.price}</p>
                </div>
            ))}
        </div>
      </div>

      {/* Main Feed with Filters */}
      <div className="px-4 pb-24">
         <div className="flex justify-between items-end mb-4">
            <h3 className="font-display font-bold text-gray-900 dark:text-white text-base">Fresh Listings</h3>
            <div className="flex gap-2">
                {['nearby', 'price'].map(type => (
                    <button 
                        key={type}
                        onClick={() => setSortType(type as any)}
                        className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase transition-all ${sortType === type ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400'}`}
                    >
                        {type}
                    </button>
                ))}
            </div>
         </div>

         {isDataLoading ? (
             <div className="grid grid-cols-2 gap-3">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                {sortedProducts.map(product => {
                    const vendor = vendors.find(v => v.vendorId === product.vendorId);
                    const isFav = favorites.includes(product.id);
                    const isInCart = cart.some(item => item.productId === product.id);

                    return (
                        <div 
                            key={product.id} 
                            className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 transition-all duration-300 group flex flex-col h-full cursor-pointer"
                            onClick={() => navigate(`/buyer/product/${product.id}`)}
                        >
                            <div className="aspect-square w-full relative overflow-hidden bg-white dark:bg-gray-900">
                                <img src={product.images[0]} alt={product.title} className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                                <div className="absolute top-2 left-2 bg-white/90 dark:bg-darkBg/90 backdrop-blur-md px-2 py-1 rounded-lg text-[9px] font-bold shadow-sm flex items-center gap-1 z-20 text-gray-700 dark:text-gray-300">
                                     <i className="fa-solid fa-location-dot text-primary text-[8px]"></i> {product.location}
                                </div>
                                <button 
                                    className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 dark:bg-darkBg/80 backdrop-blur-sm text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors shadow-sm"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        toggleFavorite(product.id);
                                    }}
                                >
                                    <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-xs`}></i>
                                </button>
                                {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-10"><span className="bg-black text-white text-[8px] px-2 py-1 rounded font-bold uppercase">Sold Out</span></div>}
                            </div>
                            <div className="p-3 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3>
                                    <p className="text-[10px] text-gray-400 dark:text-gray-500">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <span className="text-sm font-extrabold text-gray-900 dark:text-white">₵{product.price}</span>
                                    <button 
                                        className={`w-7 h-7 rounded-full flex items-center justify-center text-white transition-all ${isInCart ? 'bg-green-500' : 'bg-black dark:bg-white dark:text-black'}`}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            if (product.stock > 0) isInCart ? removeFromCart(product.id) : addToCart(product);
                                        }}
                                    >
                                        <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-[10px]`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

