                <div className="p-4 bg-blue-50 dark:bg-primary/10 rounded-2xl border border-blue-100 dark:border-primary/20">
                     <p className="text-[10px] font-bold text-blue-700 dark:text-blue-400 uppercase flex items-center gap-2">
                        <i className="fa-solid fa-circle-info"></i> Pro Tip
                     </p>
                     <p className="text-xs text-blue-600 dark:text-blue-300 mt-1">Real images build more trust with students and increase your sales by 40%.</p>
                </div>

                <Button fullWidth size="lg" type="submit" disabled={loading || uploading} className="mt-4 shadow-xl shadow-primary/20">
                    {loading ? 'Creating Store...' : 'Launch My Store'}
                </Button>
            </form>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
