    const isCourier = currentUser?.roles.includes('courier');
    const isVendor = currentUser?.roles.includes('vendor');

    const handleCourierReg = async (e: React.FormEvent) => {
        e.preventDefault();
        await registerCourier(regForm);
        setShowCourierReg(false);
    };

    return (
        <div className="px-4 mt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-3">Your Roles</h3>
            <div className="flex gap-2 mb-4 overflow-x-auto pb-2 hide-scrollbar">
