                {isVendor && (
                    <button 
                        onClick={() => { switchRole('vendor'); navigate('/vendor/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'vendor' ? 'bg-secondary text-white border-secondary shadow-lg shadow-secondary/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                    >
                        <i className="fa-solid fa-store block mb-1"></i> Vendor
