                )}
                {isCourier && deliveryProfile?.status === 'approved' && (
                    <button 
                        onClick={() => { switchRole('courier'); navigate('/delivery/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'courier' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-600/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
