import React, { useState, useEffect, useRef } from 'react';
import { useApp } from '../context';
import { Button, Card, Input, Badge, Avatar, Spinner } from '../components/UI';
import { useNavigate, Link } from 'react-router-dom';
import { Role, TransportType } from '../types';

// --- Order Progress Tracker ---
const OrderProgress: React.FC<{ order: any }> = ({ order }) => {
    const steps = order.deliveryOption === 'delivery' 
        ? ['placed', 'received', 'preparing', 'courier_assigned', 'delivering', 'delivered']
        : ['placed', 'received', 'preparing', 'ready_for_pickup', 'delivered'];

    const currentIndex = steps.indexOf(order.status);

    return (
        <div className="py-4">
            <div className="flex justify-between relative">
                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gray-100 dark:bg-gray-800 -translate-y-1/2 z-0"></div>
                <div 
                    className="absolute top-1/2 left-0 h-0.5 bg-primary -translate-y-1/2 z-0 transition-all duration-500"
                    style={{ width: `${Math.max(0, (currentIndex / (steps.length - 1)) * 100)}%` }}
                ></div>
                {steps.map((step, idx) => (
                    <div key={step} className="relative z-10 flex flex-col items-center">
                        <div className={`w-3 h-3 rounded-full border-2 transition-colors duration-300 ${idx <= currentIndex ? 'bg-primary border-primary' : 'bg-white dark:bg-darkSurface border-gray-200 dark:border-gray-700'}`}></div>
                    </div>
                ))}
            </div>
            <div className="flex justify-between mt-2">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Start</span>
                <span className="text-[10px] font-bold text-primary uppercase tracking-tighter">{order.status.replace('_', ' ')}</span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Done</span>
            </div>
        </div>
    );
};

// --- Profile Header ---
const ProfileHeader: React.FC = () => {
    const { currentUser, updateProfile, uploadFile } = useApp();
    const [editing, setEditing] = useState(false);
    const [name, setName] = useState(currentUser?.name || '');
    const [address, setAddress] = useState(currentUser?.address || '');
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if(e.target.files?.[0]) {
            setUploading(true);
            const url = await uploadFile(e.target.files[0], 'avatars');
            if(url) await updateProfile({ avatarUrl: url });
            setUploading(false);
        }
    };

    const handleSave = async () => {
        await updateProfile({ name, address });
        setEditing(false);
    };

    return (
        <div className="bg-white dark:bg-darkSurface p-6 rounded-b-[2.5rem] shadow-sm text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-24 bg-gradient-to-br from-primary/5 to-secondary/5 -z-10"></div>
            <div className="flex justify-center mb-4 relative">
                <div className="relative group">
                    <Avatar src={currentUser?.avatarUrl} name={currentUser?.name || ''} size="2xl" className="border-4 border-white dark:border-darkBg shadow-lg" />
                    <button 
                        onClick={() => fileRef.current?.click()}
                        className="absolute bottom-0 right-0 w-8 h-8 bg-gray-900 text-white rounded-full flex items-center justify-center shadow-lg hover:bg-primary transition-colors"
                    >
                        <i className={`fa-solid ${uploading ? 'fa-spinner fa-spin' : 'fa-camera'} text-xs`}></i>
                    </button>
                </div>
                <input type="file" ref={fileRef} hidden onChange={handleAvatar} />
            </div>

            {editing ? (
                <div className="space-y-3 max-w-xs mx-auto animate-fade-in">
                    <Input value={name} onChange={e => setName(e.target.value)} placeholder="Full Name" className="text-center" />
                    <Input value={address} onChange={e => setAddress(e.target.value)} placeholder="Campus Location" className="text-center" />
                    <div className="flex gap-2">
                        <Button fullWidth size="sm" onClick={handleSave}>Save</Button>
                        <Button variant="secondary" fullWidth size="sm" onClick={() => setEditing(false)}>Cancel</Button>
                    </div>
                </div>
            ) : (
                <div className="animate-fade-in">
                    <h1 className="text-2xl font-display font-black text-gray-900 dark:text-white">{currentUser?.name}</h1>
                    <p className="text-gray-400 dark:text-gray-500 text-sm font-medium mb-1">{currentUser?.email}</p>
                    <p className="text-xs text-primary font-bold flex items-center justify-center gap-1">
                        <i className="fa-solid fa-location-dot"></i> {currentUser?.address || 'Set Location'}
                    </p>
                    <button onClick={() => setEditing(true)} className="mt-4 text-xs font-bold text-gray-400 dark:text-gray-500 bg-gray-50 dark:bg-gray-800 px-4 py-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
                        Edit Profile
                    </button>
                </div>
            )}
        </div>
    );
};

// --- Store Management (Vendor Specific) ---
const StoreSettings: React.FC = () => {
    const { vendors, currentUser, uploadFile, registerVendor, showToast } = useApp();
    const vendor = vendors.find(v => v.userId === currentUser?.id);
    const [uploading, setUploading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);

    // State for info editing
    const [storeDetails, setStoreDetails] = useState({
        storeName: vendor?.storeName || '',
        storeDescription: vendor?.storeDescription || '',
        location: vendor?.location || '',
        contactPhone: vendor?.contactPhone || ''
    });

    // Synchronize local edit state when vendor context updates
    useEffect(() => {
        if (vendor) {
            setStoreDetails({
                storeName: vendor.storeName,
                storeDescription: vendor.storeDescription || '',
                location: vendor.location,
                contactPhone: vendor.contactPhone || ''
            });
        }
    }, [vendor]);

    const fileRef = useRef<HTMLInputElement>(null);

    if (!vendor) return null;

    const handlePhotoUpdate = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if(e.target.files?.[0]) {
            setUploading(true);
            const url = await uploadFile(e.target.files[0], 'avatars');
            if(url) {
                // IMPORTANT: Use the actual data from the vendor context to ensure we don't 
                // overwrite existing fields with outdated local state if they weren't being edited.
                const result = await registerVendor({
                    storeName: vendor.storeName,
                    storeDescription: vendor.storeDescription,
                    location: vendor.location,
                    contactPhone: vendor.contactPhone || '',
                    storeAvatarUrl: url
                });
                if (result.success) {
                    showToast("Store photo successfully updated", "success");
                }
            }
            setUploading(false);
            if (fileRef.current) fileRef.current.value = '';
        }
    };

    const handleSaveDetails = async () => {
        const result = await registerVendor({
            ...storeDetails,
            storeAvatarUrl: vendor.storeAvatarUrl
        });
        if (result.success) {
            setIsEditing(false);
            showToast("Store details updated", "success");
        }
    };

    return (
        <div className="px-4 mt-6 animate-fade-in">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-3">Store Identity</h3>
            <Card className="p-6 bg-white dark:bg-darkSurface border-gray-100 dark:border-gray-800 relative group overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>

                <div className="flex flex-col md:flex-row items-center gap-6 relative z-10">
                    <div className="relative">
                        <div className="w-24 h-24 rounded-2xl overflow-hidden border-2 border-primary shadow-lg bg-gray-100 dark:bg-gray-900 group relative">
                            <img 
                                key={vendor.storeAvatarUrl} // Force element re-render on change
                                src={vendor.storeAvatarUrl || 'https://via.placeholder.com/150?text=Shop'} 
                                alt={vendor.storeName} 
                                className="w-full h-full object-cover transition-opacity duration-300" 
                            />
                            {uploading && (
                                <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center">
                                    <Spinner />
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => fileRef.current?.click()}
                            disabled={uploading}
                            className="absolute -bottom-2 -right-2 w-8 h-8 bg-primary text-white rounded-xl shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-all disabled:opacity-50 disabled:active:scale-100"
                            title="Update Shop Front Image"
                        >
                            <i className={`fa-solid ${uploading ? 'fa-spinner fa-spin' : 'fa-camera'} text-xs`}></i>
                        </button>
                        <input type="file" ref={fileRef} hidden onChange={handlePhotoUpdate} accept="image/*" />
                    </div>

                    <div className="flex-1 text-center md:text-left">
                        {isEditing ? (
                            <div className="space-y-3">
                                <Input value={storeDetails.storeName} onChange={e => setStoreDetails({...storeDetails, storeName: e.target.value})} label="Store Name" className="mb-2" />
                                <Input value={storeDetails.location} onChange={e => setStoreDetails({...storeDetails, location: e.target.value})} label="Location" className="mb-2" />
                                <div className="flex gap-2">
                                    <Button size="sm" onClick={handleSaveDetails}>Save</Button>
                                    <Button variant="secondary" size="sm" onClick={() => setIsEditing(false)}>Cancel</Button>
                                </div>
                            </div>
                        ) : (
                            <>
                                <h4 className="text-lg font-display font-black text-gray-900 dark:text-white mb-1">{vendor.storeName}</h4>
                                <p className="text-xs text-gray-500 dark:text-gray-400 font-medium mb-3 flex items-center justify-center md:justify-start gap-1">
                                    <i className="fa-solid fa-location-dot text-primary"></i> {vendor.location}
                                </p>
                                <button 
                                    onClick={() => setIsEditing(true)}
                                    className="text-[10px] font-black text-primary uppercase tracking-widest hover:underline"
                                >
                                    Edit Store Info
                                </button>
                            </>
                        )}
                    </div>
                </div>

                <div className="mt-6 pt-4 border-t border-gray-50 dark:border-gray-800">
                    <p className="text-[10px] text-gray-400 dark:text-gray-500 leading-relaxed italic">
                        * Real images of your shop front or hostel entrance help buyers find you physically on campus.
                    </p>
                </div>
            </Card>
        </div>
    );
};

