    const { currentUser, currentRole, switchRole, registerCourier, couriers } = useApp();
    const navigate = useNavigate();
    const [showCourierReg, setShowCourierReg] = useState(false);
    const [regForm, setRegForm] = useState({ fullName: '', vehicleType: 'Motorbike', transportType: 'Motorbike' as TransportType, payoutMethod: 'MoMo', deliveryRadius: 5 });

    const deliveryProfile = couriers.find(d => d.userId === currentUser?.id);
    const isCourier = currentUser?.roles.includes('courier');
    const isVendor = currentUser?.roles.includes('vendor');

    const handleCourierReg = async (e: React.FormEvent) => {
        e.preventDefault();
        await registerCourier(regForm);
        setShowCourierReg(false);
    };

    return (
        <div className="px-4 mt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-3">Your Roles</h3>
            <div className="flex gap-2 mb-4 overflow-x-auto pb-2 hide-scrollbar">
                <button 
                    onClick={() => { switchRole('buyer'); navigate('/buyer/dashboard'); }}
                    className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'buyer' ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                >
                    <i className="fa-solid fa-bag-shopping block mb-1"></i> Buyer
                </button>
                {isVendor && (
                    <button 
                        onClick={() => { switchRole('vendor'); navigate('/vendor/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'vendor' ? 'bg-secondary text-white border-secondary shadow-lg shadow-secondary/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                    >
                        <i className="fa-solid fa-store block mb-1"></i> Vendor
                    </button>
                )}
                {isCourier && deliveryProfile?.status === 'approved' && (
                    <button 
                        onClick={() => { switchRole('courier'); navigate('/delivery/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'courier' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-600/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                    >
                        <i className="fa-solid fa-motorcycle block mb-1"></i> Delivery
                    </button>
                )}
            </div>

            {!isCourier && !deliveryProfile && (
                <Card className="p-4 bg-gradient-to-br from-blue-600 to-blue-800 text-white border-none shadow-blue-200">
                    <h4 className="font-bold text-sm mb-1">Earn as you walk</h4>
                    <p className="text-[10px] opacity-80 mb-3">Deliver orders across campus and earn ₵10+ per trip.</p>
                    <Button variant="secondary" size="sm" onClick={() => setShowCourierReg(true)}>Register as Courier</Button>
                </Card>
            )}

            {deliveryProfile?.status === 'pending' && (
                <div className="bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-100 dark:border-yellow-900/20 p-4 rounded-2xl flex items-center gap-3">
                    <i className="fa-solid fa-clock text-yellow-500"></i>
                    <p className="text-xs font-bold text-yellow-700 dark:text-yellow-500">Courier application is under review.</p>
                </div>
            )}

            {!isVendor && (
                <Card className="p-4 mt-3 bg-gradient-to-br from-pink-50 to-rose-600 text-white border-none shadow-pink-200">
                    <h4 className="font-bold text-sm mb-1">Sell on LYNQED</h4>
                    <p className="text-[10px] opacity-80 mb-3">Launch your business and reach campus customers instantly.</p>
                    <Button variant="secondary" size="sm" onClick={() => navigate('/vendor/onboarding')}>Open Your Store</Button>
                </Card>
            )}

            {showCourierReg && (
                <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
                    <Card className="p-6 w-full max-w-md rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface">
                        <h3 className="text-xl font-bold mb-1 dark:text-white">Courier Registration</h3>
                        <p className="text-xs text-gray-400 mb-6">Join our logistics fleet</p>
