                                    {['Walking', 'Bicycle', 'Motorbike', 'Other'].map(type => (
                                        <div 
                                            key={type}
                                            onClick={() => setRegForm({...regForm, transportType: type as any})}
                                            className={`p-3 rounded-xl border-2 text-center text-xs font-bold transition-all cursor-pointer ${regForm.transportType === type ? 'border-primary bg-primary/5 text-primary' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
