-- Ensure the vendors table has a unique constraint on user_id 
-- This allows the UPSERT command to replace the old profile instead of trying to create a new one.
ALTER TABLE public.vendors DROP CONSTRAINT IF EXISTS vendors_user_id_key;
ALTER TABLE public.vendors ADD CONSTRAINT vendors_user_id_key UNIQUE (user_id);

-- Ensure the Storage bucket 'lynqed-assets' is public so images reflect in the search page
-- If this isn't set, images may show in the dashboard (where auth is active) but not on the map.
UPDATE storage.buckets SET public = true WHERE id = 'lynqed-assets';

