                                </div>
                                <div className="flex gap-4">
                                    <img src={p.images[0]} className="w-20 h-20 rounded-xl object-cover bg-white dark:bg-darkBg shadow-sm" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1">{p.title}</h4>
                                        <p className="font-bold text-primary dark:text-primaryLight text-lg">{p.currency}{p.price}</p>
                                        <div className="flex items-center gap-1 mt-1">
                                            <div className="flex text-yellow-400 text-[10px]">
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star-half-stroke"></i>
                                            </div>
                                            <span className="text-[10px] text-gray-400">(4.5)</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="mt-6 flex flex-col gap-2">
                                    <div className="flex gap-2">
                                        <Button className="flex-1 shadow-lg shadow-primary/20" onClick={() => navigate(`/buyer/product/${p.id}`)}>View Details</Button>
                                        {whatsappUrl && (
                                            <a 
                                                href={whatsappUrl}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="w-12 h-12 bg-[#25D366] text-white rounded-2xl flex items-center justify-center shadow-lg hover:scale-105 active:scale-95 transition-all"
                                                title="Chat on WhatsApp"
                                            >
                                                <i className="fa-brands fa-whatsapp text-2xl"></i>
                                            </a>
                                        )}
                                    </div>
                                    <button 
                                        className="text-xs font-bold text-gray-400 dark:text-gray-500 hover:text-primary py-2 transition-colors"
                                        onClick={() => { setSelectedProductId(null); setIsDrawerOpen(true); }}
                                    >
                                        Back to Results
                                    </button>
                                </div>
                            </div>
                        );
                    })()
                ) : (
                    // List View
                    approvedProducts.length === 0 ? (
                        <div className="text-center py-10 text-gray-400 dark:text-gray-600 transition-colors">
                            <i className="fa-solid fa-magnifying-glass text-3xl mb-3 opacity-20"></i>
