                    ) : (
                        approvedProducts.map(product => {
                            const vendor = vendors.find(v => v.vendorId === product.vendorId);
                            const ts = Date.now();
                            const avatarUrl = vendor?.storeAvatarUrl ? `${vendor.storeAvatarUrl}?v=${ts}` : undefined;
                            return (
                                <div 
                                    key={product.id} 
                                    className="flex bg-white dark:bg-darkBg/50 border border-gray-100 dark:border-gray-800 rounded-3xl p-3 shadow-sm active:scale-[0.98] transition-all cursor-pointer hover:shadow-md hover:border-primary/20 group" 
