                </h3>
            </div>

            <div className="grid grid-cols-1 gap-4">
                {selectedProductId ? (
                    // Selected Item View
                    (() => {
                        const p = products.find(prod => prod.id === selectedProductId);
                        if (!p) return null;
                        const v = vendors.find(vend => vend.vendorId === p.vendorId);
                        const ts = Date.now();
                        const avatarUrl = v?.storeAvatarUrl ? `${v.storeAvatarUrl}?v=${ts}` : undefined;

                        const whatsappUrl = v?.contactPhone 
                            ? `https://wa.me/${v.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${v.storeName}, I found your product "${p.title}" on the LYNQED Map!`
                            : null;

                        return (
                            <div className="bg-blue-50 dark:bg-primary/10 border border-blue-100 dark:border-primary/20 rounded-2xl p-4 shadow-sm animate-fade-in transition-colors">
                                <div className="flex items-center gap-4 mb-4 pb-4 border-b border-blue-100/50 dark:border-primary/10">
                                     <div className="w-16 h-16 rounded-2xl overflow-hidden border-2 border-primary shadow-sm bg-white dark:bg-darkBg">
                                        <img src={avatarUrl} className="w-full h-full object-cover" />
                                     </div>
                                     <div>
                                         <p className="text-[10px] font-bold text-primary uppercase tracking-widest">Identified Store</p>
                                         <h4 className="font-display font-bold text-gray-900 dark:text-white text-lg leading-tight">{v?.storeName}</h4>
                                         <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">📍 {v?.location}</p>
                                     </div>
                                </div>
                                <div className="flex gap-4">
                                    <img src={p.images[0]} className="w-20 h-20 rounded-xl object-cover bg-white dark:bg-darkBg shadow-sm" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1">{p.title}</h4>
                                        <p className="font-bold text-primary dark:text-primaryLight text-lg">{p.currency}{p.price}</p>
                                        <div className="flex items-center gap-1 mt-1">
                                            <div className="flex text-yellow-400 text-[10px]">
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star"></i>
                                                <i className="fa-solid fa-star-half-stroke"></i>
                                            </div>
                                            <span className="text-[10px] text-gray-400">(4.5)</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="mt-6 flex flex-col gap-2">
                                    <div className="flex gap-2">
                                        <Button className="flex-1 shadow-lg shadow-primary/20" onClick={() => navigate(`/buyer/product/${p.id}`)}>View Details</Button>
                                        {whatsappUrl && (
                                            <a 
                                                href={whatsappUrl}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="w-12 h-12 bg-[#25D366] text-white rounded-2xl flex items-center justify-center shadow-lg hover:scale-105 active:scale-95 transition-all"
                                                title="Chat on WhatsApp"
                                            >
                                                <i className="fa-brands fa-whatsapp text-2xl"></i>
                                            </a>
                                        )}
                                    </div>
                                    <button 
                                        className="text-xs font-bold text-gray-400 dark:text-gray-500 hover:text-primary py-2 transition-colors"
                                        onClick={() => { setSelectedProductId(null); setIsDrawerOpen(true); }}
                                    >
                                        Back to Results
                                    </button>
                                </div>
                            </div>
                        );
                    })()
                ) : (
                    // List View
                    approvedProducts.length === 0 ? (
                        <div className="text-center py-10 text-gray-400 dark:text-gray-600 transition-colors">
                            <i className="fa-solid fa-magnifying-glass text-3xl mb-3 opacity-20"></i>
                            <p>No listings found for "{query}"</p>
                        </div>
                    ) : (
                        approvedProducts.map(product => {
                            const vendor = vendors.find(v => v.vendorId === product.vendorId);
                            const ts = Date.now();
                            const avatarUrl = vendor?.storeAvatarUrl ? `${vendor.storeAvatarUrl}?v=${ts}` : undefined;
                            return (
                                <div 
                                    key={product.id} 
                                    className="flex bg-white dark:bg-darkBg/50 border border-gray-100 dark:border-gray-800 rounded-3xl p-3 shadow-sm active:scale-[0.98] transition-all cursor-pointer hover:shadow-md hover:border-primary/20 group" 
                                    onClick={() => handleProductSelect(product.id)}
                                >
