import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Button, Avatar } from '../components/UI';
import { INITIAL_LOCATION_CACHE } from '../constants';

// Define Leaflet on window
declare global {
    interface Window {
        L: any;
    }
}

export const SearchPage: React.FC = () => {
  const { products, vendors, refreshData } = useApp();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [isDrawerOpen, setIsDrawerOpen] = useState(true);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markersLayerRef = useRef<any>(null); 
  const routingLayerRef = useRef<any>(null);

  // Persistent coordinate cache to improve speed and accuracy
  // Wrap IIFE in extra parentheses to clarify it's a single argument expression to the useRef hook
  const coordCache = useRef<Record<string, [number, number]>>((() => {
      try {
          const saved = localStorage.getItem('lynqed_geo_cache');
          return saved ? { ...INITIAL_LOCATION_CACHE, ...JSON.parse(saved) } : INITIAL_LOCATION_CACHE;
      } catch { return INITIAL_LOCATION_CACHE; }
  })());

  const approvedProducts = products.filter(p => 
    p.status === 'approved' && 
    p.title.toLowerCase().includes(query.toLowerCase())
  );

  // --- Helper: Multi-Pass Smart Geocoding ---
  const getCoordinates = async (locationName: string): Promise<[number, number]> => {
      const cleanName = locationName.toLowerCase().trim();

      // 1. Check local cache first
      if (coordCache.current[cleanName]) return coordCache.current[cleanName];

      // 2. Check for partial matches in cache (e.g., "Legon Hall Annex" matches "Legon")
      const partialKey = Object.keys(coordCache.current).find(k => cleanName.includes(k) || k.includes(cleanName));
      if (partialKey) return coordCache.current[partialKey];

      try {
          // Pass 1: Campus Context (High Priority)
          const campusQuery = `${locationName}, University of Ghana, Legon`;
          let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(campusQuery)}`);
          let data = await response.json();

          // Pass 2: General Ghana Context (Fallback)
          if (!data || data.length === 0) {
              response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(locationName)}, Ghana`);
              data = await response.json();
          }

          if (data && data.length > 0) {
              const coords: [number, number] = [parseFloat(data[0].lat), parseFloat(data[0].lon)];
              coordCache.current[cleanName] = coords;
              // Persist for future use
              localStorage.setItem('lynqed_geo_cache', JSON.stringify(coordCache.current));
              return coords;
          }
      } catch (e) { 
          console.warn(`Geocoding service unavailable for: ${locationName}`, e); 
      }

      // Default to campus center if everything fails
      return INITIAL_LOCATION_CACHE['legon'];
  };

  // 1. Initialize Map
  useEffect(() => {
      if (!mapContainerRef.current || mapInstanceRef.current) return;

      if (window.L) {
        const defaultCenter = [5.6506, -0.1962]; // Center on Legon

        const map = window.L.map(mapContainerRef.current, {
            zoomControl: false,
            attributionControl: false
        }).setView(defaultCenter, 14);

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            attribution: '&copy; OpenStreetMap',
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        const markersLayer = window.L.layerGroup().addTo(map);
        const routingLayer = window.L.layerGroup().addTo(map);

        markersLayerRef.current = markersLayer;
        routingLayerRef.current = routingLayer;
        mapInstanceRef.current = map;
      }

      refreshData();

      return () => {
          if (mapInstanceRef.current) {
              mapInstanceRef.current.remove();
              mapInstanceRef.current = null;
              markersLayerRef.current = null;
              routingLayerRef.current = null;
          }
      };
  }, []); 

  // 2. Plot Vendors with identifying Popups
  useEffect(() => {
      if (!mapInstanceRef.current || !markersLayerRef.current || !window.L) return;

      const map = mapInstanceRef.current;
      const markersLayer = markersLayerRef.current;
      const routingLayer = routingLayerRef.current;

      const plotVendors = async () => {
          markersLayer.clearLayers();
          routingLayer.clearLayers();

          const activeVendors = vendors.filter(v => v.isApproved);
          const userPos: [number, number] = [5.6506, -0.1962]; 

          // Draw User Pin
          const userIcon = window.L.divIcon({
              className: 'custom-user-pin',
              html: `<div class="w-4 h-4 bg-primary rounded-full border-2 border-white dark:border-darkBg shadow-glow pulse-ring"></div>`,
              iconSize: [16, 16]
          });
          window.L.marker(userPos, { icon: userIcon }).addTo(markersLayer);

          for (const v of activeVendors) {
                const position = await getCoordinates(v.location);

                // Jitter logic to separate markers in the same hall
                const jitterLat = (Math.random() - 0.5) * 0.0006;
                const jitterLng = (Math.random() - 0.5) * 0.0006;
                const finalPos: [number, number] = [position[0] + jitterLat, position[1] + jitterLng];

                const isSelected = selectedProductId && products.find(p => p.id === selectedProductId)?.vendorId === v.vendorId;

                if (isSelected) {
                    const polyline = window.L.polyline([userPos, finalPos], {
                        color: '#6366f1', 
                        weight: 4,
                        opacity: 0.6,
                        dashArray: '8, 12',
                        lineCap: 'round'
                    }).addTo(routingLayer);
                    map.fitBounds(polyline.getBounds(), { padding: [80, 80] });
                }

                const ts = Date.now();
                const avatarUrl = v.storeAvatarUrl ? `${v.storeAvatarUrl}?v=${ts}` : `https://ui-avatars.com/api/?name=${encodeURIComponent(v.storeName)}&background=6366f1&color=fff`;

                const customIcon = window.L.divIcon({
                    className: 'custom-map-pin',
                    html: `
                        <div class="relative group cursor-pointer ${isSelected ? 'z-50 scale-125' : ''}">
                            <div class="w-11 h-11 bg-white dark:bg-darkSurface rounded-2xl p-0.5 shadow-float border-2 ${isSelected ? 'border-primary ring-4 ring-primary/20' : 'border-white dark:border-gray-800'} overflow-hidden transform transition-all hover:scale-110 active:scale-95">
                                <img src="${avatarUrl}" class="w-full h-full object-cover bg-gray-100 dark:bg-darkBg rounded-xl" />
                            </div>
                            <div class="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0 border-l-[5px] border-l-transparent border-r-[5px] border-r-transparent border-t-[7px] ${isSelected ? 'border-t-primary' : 'border-t-white dark:border-t-gray-800'}"></div>
                        </div>
                    `,
                    iconSize: [44, 44],
                    iconAnchor: [22, 48]
                });

                const marker = window.L.marker(finalPos, { icon: customIcon });

                // Information Popup
                marker.bindPopup(`
                    <div class="p-2 text-center" style="min-width: 130px;">
                        <p class="font-display font-black text-gray-900 text-sm m-0 leading-tight">${v.storeName}</p>
                        <p class="text-[10px] text-gray-400 m-0 mt-1 uppercase font-bold tracking-tight">📍 ${v.location}</p>
                        <div class="flex items-center justify-center gap-1 mt-1 text-yellow-400 text-[10px]">
                            <i class="fa-solid fa-star"></i>
                            <span class="text-gray-600 font-black">${v.rating || '5.0'}</span>
                        </div>
                        <button onclick="window.location.hash='#/store/${v.vendorId}'" class="mt-2.5 w-full text-[10px] bg-gray-900 text-white dark:bg-primary px-3 py-2 rounded-lg font-black uppercase shadow-sm active:scale-95 transition-all">Visit Store</button>
                    </div>
                `, {
                    closeButton: false,
                    className: 'custom-leaflet-popup'
                });

                markersLayer.addLayer(marker);
          }
      };

      plotVendors();

  }, [vendors, selectedProductId, products]);

  const handleProductSelect = (pid: string) => {
      setSelectedProductId(pid);
      setIsDrawerOpen(false); 
  };

  const handleBack = (e: React.MouseEvent) => {
      e.preventDefault();
      if (window.history.length > 1) navigate(-1);
      else navigate('/buyer/dashboard', { replace: true });
  };

  return (
    <div className="relative h-screen w-full overflow-hidden bg-gray-100 dark:bg-darkBg flex flex-col transition-colors duration-300">

      {/* Floating Search Bar */}
      <div className="absolute top-4 left-4 right-4 z-[60] animate-slide-up">
        <div className="bg-white/95 dark:bg-darkSurface/95 backdrop-blur-md rounded-2xl shadow-float flex items-center p-3 border border-white/20 dark:border-white/5">
            <button 
                type="button"
                onClick={handleBack}
                className="mr-3 w-9 h-9 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-gray-500 dark:text-gray-400"
            >
                <i className="fa-solid fa-arrow-left"></i>
            </button>
            <input 
                autoFocus
                value={query}
                onChange={(e) => { setQuery(e.target.value); setSelectedProductId(null); setIsDrawerOpen(true); }}
                placeholder="Find specific halls or stores..."
                className="flex-grow bg-transparent outline-none text-sm text-gray-800 dark:text-white placeholder-gray-400"
            />
             {(query || selectedProductId) && <i className="fa-solid fa-xmark text-gray-400 cursor-pointer p-2" onClick={() => { setQuery(''); setSelectedProductId(null); setIsDrawerOpen(true); }}></i>}
        </div>
      </div>

      {/* Map Surface */}
      <div className="absolute inset-0 z-0" onClick={() => setIsDrawerOpen(false)}>
          <div ref={mapContainerRef} className="w-full h-full outline-none" />
      </div>

      {/* Results Drawer */}
      <div 
        className={`absolute left-0 right-0 bottom-0 bg-white dark:bg-darkSurface rounded-t-[2.5rem] shadow-[0_-10px_40px_rgba(0,0,0,0.1)] dark:shadow-[0_-10px_40px_rgba(0,0,0,0.4)] z-30 transition-all duration-500 cubic-bezier(0.32, 0.72, 0, 1) flex flex-col ${isDrawerOpen ? 'h-[65vh]' : 'h-[18vh]'}`}
      >
        <div 
            className="w-full py-4 flex justify-center cursor-grab active:cursor-grabbing"
            onClick={() => setIsDrawerOpen(!isDrawerOpen)}
        >
            <div className="w-12 h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
        </div>

        <div className="flex-grow overflow-y-auto px-5 pb-20 hide-scrollbar">
            <div className="flex justify-between items-center mb-6 sticky top-0 bg-white dark:bg-darkSurface py-2 z-10">
                <h3 className="font-bold text-gray-800 dark:text-white text-lg font-display">
                    {selectedProductId ? 'Store Location' : `${approvedProducts.length} Listings Nearby`}
                </h3>
            </div>

            <div className="grid grid-cols-1 gap-4">
                {selectedProductId ? (
                    // Focused Item Detail
                    (() => {
                        const p = products.find(prod => prod.id === selectedProductId);
                        if (!p) return null;
                        const v = vendors.find(vend => vend.vendorId === p.vendorId);
                        const ts = Date.now();
                        const avatarUrl = v?.storeAvatarUrl ? `${v.storeAvatarUrl}?v=${ts}` : undefined;

                        return (
                            <div className="bg-indigo-50 dark:bg-primary/5 border border-indigo-100 dark:border-primary/20 rounded-[2rem] p-5 shadow-sm animate-fade-in">
                                <div className="flex items-center gap-4 mb-5 pb-5 border-b border-indigo-100/50 dark:border-primary/10">
                                     <div className="w-14 h-14 rounded-xl overflow-hidden border-2 border-primary shadow-sm bg-white dark:bg-darkBg">
                                        <img src={avatarUrl} className="w-full h-full object-cover" />
                                     </div>
                                     <div>
                                         <p className="text-[9px] font-black text-primary uppercase tracking-[0.2em] mb-1">Identified Store</p>
                                         <h4 className="font-display font-black text-gray-900 dark:text-white text-lg leading-tight">{v?.storeName}</h4>
                                         <p className="text-xs text-gray-500 font-bold">📍 {v?.location}</p>
                                     </div>
                                </div>
                                <div className="flex gap-4">
                                    <img src={p.images[0]} className="w-20 h-20 rounded-2xl object-cover bg-white dark:bg-darkBg shadow-sm border border-white dark:border-gray-800" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1">{p.title}</h4>
                                        <p className="font-black text-primary dark:text-primaryLight text-xl">₵{p.price}</p>
                                        <div className="flex items-center gap-1.5 mt-1.5 text-yellow-400 text-xs">
                                            <i className="fa-solid fa-star"></i>
                                            <span className="text-gray-400 font-bold">(4.9)</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="mt-6 flex gap-2">
                                    <Button className="flex-1 shadow-lg shadow-primary/30 h-12" onClick={() => navigate(`/buyer/product/${p.id}`)}>View Listing</Button>
                                    <Button variant="secondary" className="px-5 h-12" onClick={() => { setSelectedProductId(null); setIsDrawerOpen(true); }}><i className="fa-solid fa-list"></i></Button>
                                </div>
                            </div>
                        );
                    })()
                ) : (
                    // Main Feed
                    approvedProducts.length === 0 ? (
                        <div className="text-center py-16 text-gray-400 opacity-60">
                            <i className="fa-solid fa-map-location-dot text-4xl mb-3"></i>
                            <p className="font-bold">No matches in this area.</p>
                        </div>
                    ) : (
                        approvedProducts.map(product => {
                            const vendor = vendors.find(v => v.vendorId === product.vendorId);
                            const ts = Date.now();
                            const avatarUrl = vendor?.storeAvatarUrl ? `${vendor.storeAvatarUrl}?v=${ts}` : undefined;
                            return (
                                <div 
                                    key={product.id} 
                                    className="flex bg-white dark:bg-darkBg/40 border border-gray-100 dark:border-gray-800 rounded-3xl p-3.5 shadow-sm active:scale-[0.98] transition-all cursor-pointer group" 
                                    onClick={() => handleProductSelect(product.id)}
                                >
                                    <div className="w-24 h-24 flex-shrink-0 bg-gray-50 dark:bg-darkBg rounded-2xl overflow-hidden border border-white dark:border-gray-800 shadow-sm relative">
                                        <img src={product.images[0]} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={product.title} />
                                        <div className="absolute top-1.5 left-1.5 bg-white/90 dark:bg-black/60 backdrop-blur-sm px-1.5 py-0.5 rounded-lg text-[8px] font-black uppercase text-gray-900 dark:text-white border border-white/20">
                                            {product.category}
                                        </div>
                                    </div>

                                    <div className="ml-4 flex-grow flex flex-col justify-between py-0.5">
                                        <div>
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1 text-sm font-display leading-tight">{product.title}</h4>
                                                <Avatar src={avatarUrl} name={vendor?.storeName || ''} size="sm" className="w-6 h-6 ml-2" />
                                            </div>
                                            <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 mt-1 uppercase tracking-tighter">{vendor?.storeName}</p>
                                        </div>

                                        <div className="flex justify-between items-end">
                                            <span className="font-black text-gray-900 dark:text-white text-lg">₵{product.price}</span>
                                            <div className="flex items-center gap-1 text-[10px] font-bold text-gray-400 bg-gray-50 dark:bg-darkSurface px-2 py-1 rounded-lg border border-gray-100 dark:border-gray-800">
                                                <i className="fa-solid fa-location-dot text-primary text-[8px]"></i>
                                                <span className="truncate max-w-[90px]">{product.location}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })
                    )
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Button, Avatar } from '../components/UI';
import { INITIAL_LOCATION_CACHE } from '../constants';

// Define Leaflet on window
declare global {
    interface Window {
        L: any;
    }
}

export const SearchPage: React.FC = () => {
  const { products, vendors, refreshData } = useApp();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [isDrawerOpen, setIsDrawerOpen] = useState(true);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markersLayerRef = useRef<any>(null); 
  const routingLayerRef = useRef<any>(null);

  // Persistent coordinate cache
  const coordCache = useRef<Record<string, [number, number]>>((() => {
      try {
          const saved = localStorage.getItem('lynqed_geo_cache');
          return saved ? { ...INITIAL_LOCATION_CACHE, ...JSON.parse(saved) } : INITIAL_LOCATION_CACHE;
      } catch { return INITIAL_LOCATION_CACHE; }
  })());

  const approvedProducts = products.filter(p => 
    p.status === 'approved' && 
    p.title.toLowerCase().includes(query.toLowerCase())
  );

  // Helper: Get robust image URL for vendors
  const getVendorAvatar = (v: any) => {
      if (v?.storeAvatarUrl) {
          // Add a small timestamp to bust cache if the user just updated it
          return `${v.storeAvatarUrl}?v=${Date.now().toString().slice(-5)}`;
      }
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(v?.storeName || 'Store')}&background=6366f1&color=fff&bold=true`;
  };

  // --- Helper: Smart Geocoding ---
  const getCoordinates = async (locationName: string): Promise<[number, number]> => {
      const cleanName = locationName.toLowerCase().trim();
      if (coordCache.current[cleanName]) return coordCache.current[cleanName];

      const partialKey = Object.keys(coordCache.current).find(k => cleanName.includes(k) || k.includes(cleanName));
      if (partialKey) return coordCache.current[partialKey];

      try {
          const campusQuery = `${locationName}, University of Ghana, Legon`;
          let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(campusQuery)}`);
          let data = await response.json();

          if (!data || data.length === 0) {
              response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(locationName)}, Ghana`);
              data = await response.json();
          }

          if (data && data.length > 0) {
              const coords: [number, number] = [parseFloat(data[0].lat), parseFloat(data[0].lon)];
              coordCache.current[cleanName] = coords;
              localStorage.setItem('lynqed_geo_cache', JSON.stringify(coordCache.current));
              return coords;
          }
      } catch (e) { console.warn(`Geocoding failed for: ${locationName}`); }
      return INITIAL_LOCATION_CACHE['legon'];
  };

  // 1. Initialize Map
  useEffect(() => {
      if (!mapContainerRef.current || mapInstanceRef.current) return;

      if (window.L) {
        const defaultCenter = [5.6506, -0.1962];
        const map = window.L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView(defaultCenter, 14);

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        markersLayerRef.current = window.L.layerGroup().addTo(map);
        routingLayerRef.current = window.L.layerGroup().addTo(map);
        mapInstanceRef.current = map;
      }

      refreshData();

      return () => {
          if (mapInstanceRef.current) {
              mapInstanceRef.current.remove();
              mapInstanceRef.current = null;
          }
      };
  }, []); 

  // 2. Plot Vendors
  useEffect(() => {
      if (!mapInstanceRef.current || !markersLayerRef.current || !window.L) return;

      const markersLayer = markersLayerRef.current;
      const routingLayer = routingLayerRef.current;
      const map = mapInstanceRef.current;

      const plotVendors = async () => {
          markersLayer.clearLayers();
          routingLayer.clearLayers();

          const activeVendors = vendors.filter(v => v.isApproved);
          const userPos: [number, number] = [5.6506, -0.1962]; 

          // User Pin
          window.L.marker(userPos, { 
              icon: window.L.divIcon({
                  className: 'custom-user-pin',
                  html: `<div class="w-4 h-4 bg-primary rounded-full border-2 border-white shadow-glow pulse-ring"></div>`,
                  iconSize: [16, 16]
              }) 
          }).addTo(markersLayer);

          for (const v of activeVendors) {
                const position = await getCoordinates(v.location);
                const jitterLat = (Math.random() - 0.5) * 0.0006;
                const jitterLng = (Math.random() - 0.5) * 0.0006;
                const finalPos: [number, number] = [position[0] + jitterLat, position[1] + jitterLng];

                const isSelected = selectedProductId && products.find(p => p.id === selectedProductId)?.vendorId === v.vendorId;
                const avatarUrl = getVendorAvatar(v);

                if (isSelected) {
                    const polyline = window.L.polyline([userPos, finalPos], { color: '#6366f1', weight: 4, opacity: 0.6, dashArray: '8, 12' }).addTo(routingLayer);
                    map.fitBounds(polyline.getBounds(), { padding: [80, 80] });
                }

                const marker = window.L.marker(finalPos, { 
                    icon: window.L.divIcon({
                        className: 'custom-map-pin',
                        html: `
                            <div class="relative group cursor-pointer ${isSelected ? 'z-50 scale-125' : ''}">
                                <div class="w-11 h-11 bg-white dark:bg-darkSurface rounded-2xl p-0.5 shadow-float border-2 ${isSelected ? 'border-primary ring-4 ring-primary/20' : 'border-white dark:border-gray-800'} overflow-hidden transform transition-all">
                                    <img src="${avatarUrl}" class="w-full h-full object-cover bg-gray-100 dark:bg-darkBg rounded-xl" onerror="this.src='https://ui-avatars.com/api/?name=Shop'"/>
                                </div>
                                <div class="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0 border-l-[5px] border-l-transparent border-r-[5px] border-r-transparent border-t-[7px] ${isSelected ? 'border-t-primary' : 'border-t-white dark:border-t-gray-800'}"></div>
                            </div>
                        `,
                        iconSize: [44, 44],
                        iconAnchor: [22, 48]
                    })
                });

                marker.bindPopup(`
                    <div class="p-2 text-center" style="min-width: 130px;">
                        <p class="font-display font-black text-gray-900 text-sm m-0 leading-tight">${v.storeName}</p>
                        <p class="text-[10px] text-gray-400 m-0 mt-1 uppercase font-bold tracking-tight">📍 ${v.location}</p>
                        <button onclick="window.location.hash='#/store/${v.vendorId}'" class="mt-2.5 w-full text-[10px] bg-gray-900 text-white dark:bg-primary px-3 py-2 rounded-lg font-black uppercase active:scale-95 transition-all">Visit Store</button>
                    </div>
                `, { closeButton: false, className: 'custom-leaflet-popup' });

                markersLayer.addLayer(marker);
          }
      };

      plotVendors();

  }, [vendors, selectedProductId]);

  const handleProductSelect = (pid: string) => {
      setSelectedProductId(pid);
      setIsDrawerOpen(false); 
  };

  const handleBack = (e: React.MouseEvent) => {
      e.preventDefault();
      if (window.history.length > 1) navigate(-1);
      else navigate('/buyer/dashboard', { replace: true });
  };

  return (
    <div className="relative h-screen w-full overflow-hidden bg-gray-100 dark:bg-darkBg flex flex-col transition-colors duration-300">

      {/* Floating Search Bar */}
      <div className="absolute top-4 left-4 right-4 z-[60] animate-slide-up">
        <div className="bg-white/95 dark:bg-darkSurface/95 backdrop-blur-md rounded-2xl shadow-float flex items-center p-3 border border-white/20 dark:border-white/5">
            <button type="button" onClick={handleBack} className="mr-3 w-9 h-9 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-gray-500 dark:text-gray-400">
                <i className="fa-solid fa-arrow-left"></i>
            </button>
            <input 
                autoFocus
                value={query}
                onChange={(e) => { setQuery(e.target.value); setSelectedProductId(null); setIsDrawerOpen(true); }}
                placeholder="Find specific halls or stores..."
                className="flex-grow bg-transparent outline-none text-sm text-gray-800 dark:text-white placeholder-gray-400"
            />
             {(query || selectedProductId) && <i className="fa-solid fa-xmark text-gray-400 cursor-pointer p-2" onClick={() => { setQuery(''); setSelectedProductId(null); setIsDrawerOpen(true); }}></i>}
        </div>
      </div>

      {/* Map Surface */}
      <div className="absolute inset-0 z-0" onClick={() => setIsDrawerOpen(false)}>
          <div ref={mapContainerRef} className="w-full h-full outline-none" />
      </div>

      {/* Results Drawer */}
      <div className={`absolute left-0 right-0 bottom-0 bg-white dark:bg-darkSurface rounded-t-[2.5rem] shadow-[0_-10px_40px_rgba(0,0,0,0.1)] dark:shadow-[0_-10px_40px_rgba(0,0,0,0.4)] z-30 transition-all duration-500 cubic-bezier(0.32, 0.72, 0, 1) flex flex-col ${isDrawerOpen ? 'h-[65vh]' : 'h-[18vh]'}`}>
        <div className="w-full py-4 flex justify-center cursor-grab active:cursor-grabbing" onClick={() => setIsDrawerOpen(!isDrawerOpen)}>
            <div className="w-12 h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
        </div>

        <div className="flex-grow overflow-y-auto px-5 pb-20 hide-scrollbar">
            <div className="flex justify-between items-center mb-6 sticky top-0 bg-white dark:bg-darkSurface py-2 z-10">
                <h3 className="font-bold text-gray-800 dark:text-white text-lg font-display">
                    {selectedProductId ? 'Store Location' : `${approvedProducts.length} Listings Nearby`}
                </h3>
            </div>

            <div className="grid grid-cols-1 gap-4">
                {selectedProductId ? (
                    (() => {
                        const p = products.find(prod => prod.id === selectedProductId);
                        if (!p) return null;
                        const v = vendors.find(vend => vend.vendorId === p.vendorId);
                        const avatarUrl = getVendorAvatar(v);

                        return (
                            <div className="bg-indigo-50 dark:bg-primary/5 border border-indigo-100 dark:border-primary/20 rounded-[2rem] p-5 shadow-sm animate-fade-in">
                                <div className="flex items-center gap-4 mb-5 pb-5 border-b border-indigo-100/50 dark:border-primary/10">
                                     <div className="w-14 h-14 rounded-xl overflow-hidden border-2 border-primary shadow-sm bg-white dark:bg-darkBg">
                                        <img src={avatarUrl} className="w-full h-full object-cover" />
                                     </div>
                                     <div>
                                         <p className="text-[9px] font-black text-primary uppercase tracking-[0.2em] mb-1">Identified Store</p>
                                         <h4 className="font-display font-black text-gray-900 dark:text-white text-lg leading-tight">{v?.storeName}</h4>
                                         <p className="text-xs text-gray-500 font-bold">📍 {v?.location}</p>
                                     </div>
                                </div>
                                <div className="flex gap-4">
                                    <img src={p.images[0]} className="w-20 h-20 rounded-2xl object-cover bg-white dark:bg-darkBg shadow-sm border border-white dark:border-gray-800" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1">{p.title}</h4>
                                        <p className="font-black text-primary dark:text-primaryLight text-xl">₵{p.price}</p>
                                    </div>
                                </div>
                                <div className="mt-6 flex gap-2">
                                    <Button className="flex-1 shadow-lg shadow-primary/30 h-12" onClick={() => navigate(`/buyer/product/${p.id}`)}>View Listing</Button>
                                    <Button variant="secondary" className="px-5 h-12" onClick={() => { setSelectedProductId(null); setIsDrawerOpen(true); }}><i className="fa-solid fa-list"></i></Button>
                                </div>
                            </div>
                        );
                    })()
                ) : (
                    approvedProducts.length === 0 ? (
                        <div className="text-center py-16 text-gray-400 opacity-60">
                            <i className="fa-solid fa-map-location-dot text-4xl mb-3"></i>
                            <p className="font-bold">No matches in this area.</p>
                        </div>
                    ) : (
                        approvedProducts.map(product => {
                            const vendor = vendors.find(v => v.vendorId === product.vendorId);
                            const avatarUrl = getVendorAvatar(vendor);
                            return (
                                <div key={product.id} className="flex bg-white dark:bg-darkBg/40 border border-gray-100 dark:border-gray-800 rounded-3xl p-3.5 shadow-sm active:scale-[0.98] transition-all cursor-pointer group" onClick={() => handleProductSelect(product.id)}>
                                    <div className="w-24 h-24 flex-shrink-0 bg-gray-50 dark:bg-darkBg rounded-2xl overflow-hidden border border-white dark:border-gray-800 shadow-sm relative">
                                        <img src={product.images[0]} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={product.title} />
                                    </div>
                                    <div className="ml-4 flex-grow flex flex-col justify-between py-0.5">
                                        <div>
                                            <div className="flex justify-between items-start">
                                                <h4 className="font-bold text-gray-900 dark:text-white line-clamp-1 text-sm font-display leading-tight">{product.title}</h4>
                                                <Avatar src={avatarUrl} name={vendor?.storeName || ''} size="sm" className="w-6 h-6 ml-2" />
                                            </div>
                                            <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 mt-1 uppercase tracking-tighter">{vendor?.storeName}</p>
                                        </div>
                                        <div className="flex justify-between items-end">
                                            <span className="font-black text-gray-900 dark:text-white text-lg">₵{product.price}</span>
                                            <div className="flex items-center gap-1 text-[10px] font-bold text-gray-400 bg-gray-50 dark:bg-darkSurface px-2 py-1 rounded-lg border border-gray-100 dark:border-gray-800">
                                                <i className="fa-solid fa-location-dot text-primary text-[8px]"></i>
                                                <span className="truncate max-w-[90px]">{product.location}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })
                    )
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Button, Avatar } from '../components/UI';
import { INITIAL_LOCATION_CACHE } from '../constants';

// Define Leaflet on window
declare global {
    interface Window {
        L: any;
    }
}

export const SearchPage: React.FC = () => {
  const { products, vendors, refreshData } = useApp();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [isDrawerOpen, setIsDrawerOpen] = useState(true);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markersLayerRef = useRef<any>(null); 
  const routingLayerRef = useRef<any>(null);

  // Persistent coordinate cache
  const coordCache = useRef<Record<string, [number, number]>>((() => {
      try {
          const saved = localStorage.getItem('lynqed_geo_cache');
          if (saved) {
              const parsed = JSON.parse(saved);
              return { ...INITIAL_LOCATION_CACHE, ...parsed };
          }
      } catch (e) {
          console.error("Failed to load geo cache", e);
      }
      return INITIAL_LOCATION_CACHE;
  })());

  const approvedProducts = products.filter(p => 
    p.status === 'approved' && 
    (p.title.toLowerCase().includes(query.toLowerCase()) || 
     p.category.toLowerCase().includes(query.toLowerCase()))
  );

  // Robust Vendor Avatar Helper
  const getVendorAvatar = (v: any) => {
      if (v?.storeAvatarUrl && v.storeAvatarUrl.startsWith('http')) {
          return v.storeAvatarUrl;
      }
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(v?.storeName || 'Store')}&background=6366f1&color=fff&bold=true`;
  };

  // --- Helper: Smart Geocoding with Validation ---
  const getCoordinates = async (locationName: string): Promise<[number, number]> => {
      const cleanName = locationName.toLowerCase().trim();

      // 1. Check local cache
      if (coordCache.current[cleanName]) return coordCache.current[cleanName];

      // 2. Check for partial match
      const partialKey = Object.keys(coordCache.current).find(k => cleanName.includes(k) || k.includes(cleanName));
      if (partialKey) return coordCache.current[partialKey];

      try {
          const campusQuery = `${locationName}, University of Ghana, Legon`;
          let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(campusQuery)}`);
          let data = await response.json();

          if (!data || data.length === 0) {
              response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(locationName)}, Ghana`);
              data = await response.json();
          }

          if (data && data.length > 0) {
              const lat = parseFloat(data[0].lat);
              const lon = parseFloat(data[0].lon);
              if (!isNaN(lat) && !isNaN(lon)) {
                  const coords: [number, number] = [lat, lon];
                  coordCache.current[cleanName] = coords;
                  localStorage.setItem('lynqed_geo_cache', JSON.stringify(coordCache.current));
                  return coords;
              }
          }
      } catch (e) { 
          console.warn(`Geocoding failed for: ${locationName}`); 
      }

      // Default fallback
      return INITIAL_LOCATION_CACHE['legon'];
  };

  // 1. Initialize Map
  useEffect(() => {
      if (!mapContainerRef.current || mapInstanceRef.current) return;

      if (window.L) {
        const defaultCenter: [number, number] = [5.6506, -0.1962];
        const map = window.L.map(mapContainerRef.current, { 
            zoomControl: false, 
            attributionControl: false 
        }).setView(defaultCenter, 14);

        window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
            subdomains: 'abcd',
            maxZoom: 20
        }).addTo(map);

        markersLayerRef.current = window.L.layerGroup().addTo(map);
        routingLayerRef.current = window.L.layerGroup().addTo(map);
        mapInstanceRef.current = map;
      }

      refreshData();

      return () => {
          if (mapInstanceRef.current) {
              mapInstanceRef.current.remove();
              mapInstanceRef.current = null;
          }
      };
  }, []); 

  // 2. Plot Vendors
  useEffect(() => {
      const markersLayer = markersLayerRef.current;
      const routingLayer = routingLayerRef.current;
      const map = mapInstanceRef.current;

      if (!map || !markersLayer || !window.L) return;

      const plotVendors = async () => {
          markersLayer.clearLayers();
          routingLayer.clearLayers();

          const activeVendors = vendors.filter(v => v.isApproved);
          const userPos: [number, number] = [5.6506, -0.1962]; 

          // User Pin
          window.L.marker(userPos, { 
              icon: window.L.divIcon({
                  className: 'custom-user-pin',
                  html: `<div class="w-4 h-4 bg-primary rounded-full border-2 border-white shadow-glow pulse-ring"></div>`,
                  iconSize: [16, 16]
              }) 
          }).addTo(markersLayer);

          for (const v of activeVendors) {
                const basePos = await getCoordinates(v.location);

                // Jitter logic with NaN protection
                const jitterLat = (Math.random() - 0.5) * 0.0006;
                const jitterLng = (Math.random() - 0.5) * 0.0006;
                const finalPos: [number, number] = [basePos[0] + jitterLat, basePos[1] + jitterLng];

                // CRITICAL: Leaflet pos check to prevent '_leaflet_pos' error
                if (isNaN(finalPos[0]) || isNaN(finalPos[1])) continue;

                const isSelected = selectedProductId && products.find(p => p.id === selectedProductId)?.vendorId === v.vendorId;
                const avatarUrl = getVendorAvatar(v);

                if (isSelected) {
                    const polyline = window.L.polyline([userPos, finalPos], { 
                        color: '#6366f1', 
                        weight: 4, 
                        opacity: 0.6, 
                        dashArray: '8, 12' 
                    }).addTo(routingLayer);
                    map.fitBounds(polyline.getBounds(), { padding: [80, 80] });
                }

                const marker = window.L.marker(finalPos, { 
                    icon: window.L.divIcon({
                        className: 'custom-map-pin',
                        html: `
                            <div class="relative group cursor-pointer ${isSelected ? 'z-50 scale-125' : ''}">
                                <div class="w-11 h-11 bg-white dark:bg-darkSurface rounded-2xl p-0.5 shadow-float border-2 ${isSelected ? 'border-primary ring-4 ring-primary/20' : 'border-white dark:border-gray-800'} overflow-hidden transform transition-all duration-300">
                                    <img src="${avatarUrl}" class="w-full h-full object-cover bg-gray-100 dark:bg-darkBg rounded-xl" />
                                </div>
                                <div class="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0 border-l-[5px] border-l-transparent border-r-[5px] border-r-transparent border-t-[7px] ${isSelected ? 'border-t-primary' : 'border-t-white dark:border-t-gray-800'}"></div>
                            </div>
                        `,
                        iconSize: [44, 44],
                        iconAnchor: [22, 48]
                    })
                });

                marker.bindPopup(`
                    <div class="p-2 text-center" style="min-width: 130px;">
                        <p class="font-display font-black text-gray-900 text-sm m-0 leading-tight">${v.storeName}</p>
                        <p class="text-[10px] text-gray-400 m-0 mt-1 uppercase font-bold tracking-tight">📍 ${v.location}</p>
