                </div>

                {vendorProducts.length === 0 ? (
                    <div className="text-center py-24 bg-white dark:bg-darkSurface rounded-[2.5rem] border border-dashed border-gray-200 dark:border-gray-800">
                        <i className="fa-solid fa-box-open text-4xl mb-4 text-gray-200"></i>
                        <p className="text-gray-400 font-medium">No active listings from this vendor yet.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                        {vendorProducts.map(product => {
                            const isFav = favorites.includes(product.id);
                            const isInCart = cart.some(item => item.productId === product.id);

                            return (
                                <div 
                                    key={product.id} 
                                    className="bg-white dark:bg-darkSurface rounded-[2rem] overflow-hidden shadow-card hover:shadow-xl transition-all duration-500 group relative flex flex-col h-full cursor-pointer border border-gray-50 dark:border-gray-800/50"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-[4/5] w-full relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                        <img 
                                            src={product.images[0]} 
                                            alt={product.title} 
                                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                                        />
                                        <button 
                                            className="absolute top-3 right-3 z-10 w-9 h-9 rounded-full bg-white/90 dark:bg-darkBg/90 backdrop-blur-md border border-gray-100 dark:border-gray-800 text-gray-400 hover:text-red-500 flex items-center justify-center transition-all shadow-sm active:scale-90"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleFavorite(product.id);
                                            }}
                                        >
                                            <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-sm`}></i>
                                        </button>
                                        {product.stock === 0 && (
                                            <div className="absolute inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-10">
                                                <span className="bg-black/80 text-white text-[10px] px-3 py-1.5 rounded-full font-black uppercase tracking-widest border border-white/20">Sold Out</span>
                                            </div>
                                        )}
                                    </div>
                                    <div className="p-4 flex flex-col justify-between flex-grow">
                                        <div className="mb-2">
                                            <h3 className="text-sm text-gray-800 dark:text-white font-bold leading-snug line-clamp-2 group-hover:text-primary transition-colors">{product.title}</h3>
                                        </div>
                                        <div className="flex items-center justify-between pt-2">
                                            <span className="text-base font-black text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                                            <button 
                                                className={`w-9 h-9 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 ${product.stock === 0 ? 'bg-gray-200 dark:bg-gray-800 cursor-not-allowed text-gray-400' : isInCart ? 'bg-green-500' : 'bg-gray-900 dark:bg-white dark:text-black hover:bg-primary hover:text-white'}`}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (product.stock > 0) {
                                                        isInCart ? removeFromCart(product.id) : addToCart(product);
                                                    }
                                                }}
                                                disabled={product.stock === 0}
                                            >
                                                <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-xs`}></i>
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
