export const Checkout: React.FC = () => {
    const { cart, placeOrder, currentUser, signup, login } = useApp();
    const navigate = useNavigate();
    const [method, setMethod] = useState<'delivery' | 'pickup'>('delivery');
    const [isPlacing, setIsPlacing] = useState(false);
    const [guestEmail, setGuestEmail] = useState('');
    const [deliveryFee, setDeliveryFee] = useState(10); 

    useEffect(() => {
        if (method === 'pickup') {
            setDeliveryFee(0);
        } else {
            setDeliveryFee(15.00); 
        }
    }, [method]);

    const handleOrder = async () => {
        if (!currentUser && !guestEmail) { alert("Email required for guest checkout"); return; }

        setIsPlacing(true);

        try {
            if (!currentUser) {
                const shadowPass = 'guest123'; 
                const regRes = await signup(guestEmail, shadowPass, 'Guest User', 'buyer');

                if (!regRes.success) {
                     const loginRes = await login(guestEmail, shadowPass);
                     if (!loginRes.success) {
                         alert("This email is already registered. Please Login first.");
                         setIsPlacing(false);
                         return;
                     }
                }
            }

            await placeOrder(method, deliveryFee);
            setTimeout(() => { 
                setIsPlacing(false); 
                navigate('/buyer/orders'); 
            }, 2000);

        } catch (e) {
            console.error(e);
            setIsPlacing(false);
            alert("Checkout failed. Please try again.");
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const total = subtotal + deliveryFee;

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in pb-safe">
            <h1 className="text-2xl font-display font-bold mb-6 dark:text-white">Checkout</h1>

            {!currentUser && (
                <Card className="p-4 mb-4">
                    <h3 className="font-bold text-sm mb-2 dark:text-white">Guest Checkout</h3>
                    <Input label="Email Address" value={guestEmail} onChange={e => setGuestEmail(e.target.value)} placeholder="Enter email for receipt" />
                    <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">We'll create a temporary account for you to track this order.</p>
                </Card>
            )}

            <div className="grid grid-cols-2 gap-4 mb-6">
                <div onClick={() => setMethod('delivery')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'delivery' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-motorcycle text-xl mb-2"></i>
                    <p className="font-bold text-sm">Delivery</p>
                    <p className="text-xs opacity-70">₵{deliveryFee}</p>
                </div>
                <div onClick={() => setMethod('pickup')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'pickup' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-person-walking text-xl mb-2"></i>
                    <p className="font-bold text-sm">Pickup</p>
                    <p className="text-xs opacity-70">Free</p>
                </div>
            </div>

            <Card className="p-5">
                <h3 className="font-bold mb-4 dark:text-white">Summary</h3>
                <div className="space-y-2">
                    {cart.map(i => <div key={i.productId} className="flex justify-between text-sm dark:text-gray-400"><span>{i.product.title} x{i.quantity}</span><span className="dark:text-white">₵{i.product.price * i.quantity}</span></div>)}
                </div>
                <div className="border-t border-dashed dark:border-gray-800 my-4"></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Subtotal</span><span className="dark:text-white">₵{subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Fee</span><span className="dark:text-white">₵{deliveryFee.toFixed(2)}</span></div>
                <div className="flex justify-between font-bold text-lg mt-2 dark:text-white"><span>Total</span><span>₵{total.toFixed(2)}</span></div>
            </Card>

            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-darkSurface border-t border-gray-100 dark:border-gray-800">
                <Button fullWidth size="lg" onClick={handleOrder} disabled={isPlacing}>
                    {isPlacing ? 'Processing Order...' : `Pay ₵${total.toFixed(2)}`}
                </Button>
            </div>
        </div>
    );
};
